-- ----------------------------
-- Table structure for dataset_name
-- ----------------------------
DROP TABLE IF EXISTS `dataset_name`;
CREATE TABLE `dataset_name`  (
  `name` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `sensor_size` int NOT NULL,
  `relay_size` int NOT NULL,
  `station_size` int NOT NULL,
  `intersection_size` int NOT NULL,
  `location_lng` double NOT NULL,
  `location_lat` double NOT NULL,
  `is_dataset` int NOT NULL,
  PRIMARY KEY (`name`(10)) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = Dynamic;

